/**
 * Data 331 Desa & Kelurahan Resmi Kabupaten Banyumas
 * Sinkron 100% dengan Official GeoJSON BIG/BPS & KAK/PRD Ternakverse
 * Terdistribusi presisi di 27 Kecamatan
 * BERKAS-UTUH: banyumasDesaData.ts
 */

export interface DesaData {
    id: string; // kode_kd (e.g. 33.02.05.2001)
    kode_kd: string;
    nama: string;
    jenis: 'Desa' | 'Kelurahan';
    kecamatan_id: string;
    kecamatan_nama: string;
    kode_kec: string;
    lat: number;
    lng: number;

    // Populasi (ekor)
    ayam_potong: number;
    ayam_petelur: number;
    kambing: number;
    domba: number;
    sapi_perah: number;
    sapi_potong: number;

    // Produksi (kg & liter)
    telur_ayam: number;
    daging_ayam: number;
    daging_sapi: number;
    daging_kambing: number;
    daging_domba: number;
    susu_sapi: number;
    susu_kambing: number;
    susu_domba: number;

    // Penyakit (kasus)
    pmk: number;
    lsd: number;

    // Fasilitas (unit)
    poskeswan: number;
}

