// Lookup map by ID
const desaMap = new Map<string, DesaData>();
BANYUMAS_DESA_LIST.forEach(d => desaMap.set(d.id, d));

export function getDesaById(id: string): DesaData | undefined {
    return desaMap.get(id);
}

export function getDesaByKecamatan(kecamatanId: string): DesaData[] {
    const kId = kecamatanId.toLowerCase();
    return BANYUMAS_DESA_LIST.filter(d => 
        d.kecamatan_id.toLowerCase() === kId || 
        d.kecamatan_nama.toLowerCase() === kId
    );
}

export function getAllDesa(): DesaData[] {
    return BANYUMAS_DESA_LIST;
}
